package com.lexorion.payroll.api;
import static com.lexorion.payroll.api.CalculationDtos.*;import com.lexorion.payroll.service.CalculationService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/payroll/employees/{employeeCode}/calculations")@PreAuthorize("hasAnyRole('OWNER','ADMIN')")public class CalculationController{private final CalculationService service;public CalculationController(CalculationService s){service=s;}@GetMapping public List<CalculationResponse>list(@PathVariable String employeeCode){return service.list(employeeCode);}@PostMapping public ResponseEntity<CalculationResponse>calculate(@PathVariable String employeeCode,@Valid@RequestBody CreateCalculation r){return ResponseEntity.status(HttpStatus.CREATED).body(service.calculate(employeeCode,r));}}
